    return ChainMap(d, self.globals)

def newline(self, node: nodes.Node | None = None, extra: int = 0) -> None:
    self._new_lines = max(self._new_lines, 1 + extra)
    if node is not None and node.lineno != self._last_line:
        self._write_debug_info = node.lineno
        self._last_line = node.lineno

def list_templates(
    self,
    extensions: t.Collection[str] | None = None,
    filter_func: t.Callable[[str], bool] | None = None,
) -> list[str]:
    assert self.loader is not None, "No loader configured."
    names = self.loader.list_templates()

    if extensions is not None:
        if filter_func is not None:
            raise TypeError(
                "either extensions or filter_func can be passed, but not both"
            )

        def filter_func(x: str) -> bool:
            return "." in x and x.rsplit(".", 1)[1] in extensions

    if filter_func is not None:
        names = [name for name in names if filter_func(name)]

    return names

def get_template_locals(real_locals: t.Mapping[str, t.Any]) -> dict[str, t.Any]:
    # Start with the current template context.
    ctx: Context | None = real_locals.get("context")

    if ctx is not None:
        data: dict[str, t.Any] = ctx.get_all().copy()
    else:
        data = {}

    # Might be in a derived context that only sets local variables
    # rather than pushing a context. Local variables follow the scheme
    # l_depth_name. Find the highest-depth local that has a value for
    # each name.
    local_overrides: dict[str, tuple[int, t.Any]] = {}

    for name, value in real_locals.items():
        if not name.startswith("l_") or value is missing:
            # Not a template variable, or no longer relevant.
            continue

        try:
            _, depth_str, name = name.split("_", 2)
            depth = int(depth_str)
        except ValueError:
            continue

        cur_depth = local_overrides.get(name, (-1,))[0]

        if cur_depth < depth:
            local_overrides[name] = (depth, value)

    # Modify the context with any derived context.
    for name, (_, value) in local_overrides.items():
        if value is missing:
            data.pop(name, None)
        else:
            data[name] = value

    return data

def object_type_repr(obj: t.Any) -> str:
    if obj is None:
        return "None"
    elif obj is Ellipsis:
        return "Ellipsis"

    cls = type(obj)

    if cls.__module__ == "builtins":
        return f"{cls.__name__} object"

    return f"{cls.__module__}.{cls.__name__} object"

def do_dictsort(
    value: t.Mapping[K, V],
    case_sensitive: bool = False,
    by: 'te.Literal["key", "value"]' = "key",
    reverse: bool = False,
) -> list[tuple[K, V]]:
    if by == "key":
        pos = 0
    elif by == "value":
        pos = 1
    else:
        raise FilterArgumentError('You can only sort by either "key" or "value"')

    def sort_func(item: tuple[t.Any, t.Any]) -> t.Any:
        value = item[pos]

        if not case_sensitive:
            value = ignore_case(value)

        return value

    return sorted(value.items(), key=sort_func, reverse=reverse)

def getattr(self, obj: t.Any, attribute: str) -> t.Any | Undefined:
    try:
        value = getattr(obj, attribute)
    except AttributeError:
        try:
            return obj[attribute]
        except (TypeError, LookupError):
            pass
    else:
        fmt = self.wrap_str_format(value)
        if fmt is not None:
            return fmt
        if self.is_safe_attribute(obj, attribute, value):
            return value
        return self.unsafe_undefined(obj, attribute)
    return self.undefined(obj=obj, name=attribute)

