    environment: "Environment",
    value: "t.Iterable[V]",
    case_sensitive: bool = False,
    attribute: str | int | None = None,
) -> "t.Iterator[V]":
    getter = make_attrgetter(
        environment, attribute, postprocess=ignore_case if not case_sensitive else None
