        return {}

    return LRUCache(size)  # type: ignore

def previtem(self) -> t.Union[t.Any, "Undefined"]:
    if self.first:
        return self._undefined("there is no previous item")

    return self._before

def do_items(value: t.Mapping[K, V] | Undefined) -> t.Iterator[tuple[K, V]]:
    if isinstance(value, Undefined):
        return

    if not isinstance(value, abc.Mapping):
        raise TypeError("Can only get item pairs from a mapping.")

    yield from value.items()

def do_replace(
    eval_ctx: "EvalContext", s: str, old: str, new: str, count: int | None = None
) -> str:
    if count is None:
        count = -1

    if not eval_ctx.autoescape:
        return str(s).replace(str(old), str(new), count)

    if (
        hasattr(old, "__html__")
        or hasattr(new, "__html__")
        and not hasattr(s, "__html__")
    ):
        s = escape(s)
    else:
        s = soft_str(s)

    return s.replace(soft_str(old), soft_str(new), count)

def iter_fields(
    self,
    exclude: t.Container[str] | None = None,
    only: t.Container[str] | None = None,
) -> t.Iterator[tuple[str, t.Any]]:
    for name in self.fields:
        if (
            (exclude is None and only is None)
            or (exclude is not None and name not in exclude)
            or (only is not None and name in only)
        ):
            try:
                yield name, getattr(self, name)
            except AttributeError:
                pass

def safe_range(*args: int) -> range:
    rng = range(*args)

    if len(rng) > MAX_RANGE:
        raise OverflowError(
            "Range too big. The sandbox blocks ranges larger than"
            f" MAX_RANGE ({MAX_RANGE})."
        )

    return rng

def wrap(
    self,
    stream: t.Iterable[tuple[int, str, str]],
    name: str | None = None,
    filename: str | None = None,
) -> t.Iterator[Token]:
    for lineno, token, value_str in stream:
        if token in ignored_tokens:
            continue

        value: t.Any = value_str

        if token == TOKEN_LINESTATEMENT_BEGIN:
            token = TOKEN_BLOCK_BEGIN
        elif token == TOKEN_LINESTATEMENT_END:
            token = TOKEN_BLOCK_END
        # we are not interested in those tokens in the parser
        elif token in (TOKEN_RAW_BEGIN, TOKEN_RAW_END):
            continue
        elif token == TOKEN_DATA:
            value = self._normalize_newlines(value_str)
        elif token == "keyword":
            token = value_str
        elif token == TOKEN_NAME:
            value = value_str

            if not value.isidentifier():
                raise TemplateSyntaxError(
                    "Invalid character in identifier", lineno, name, filename
                )
        elif token == TOKEN_STRING:
            # try to unescape string
            try:
                value = (
                    self._normalize_newlines(value_str[1:-1])
                    .encode("ascii", "backslashreplace")
                    .decode("unicode-escape")
                )
            except Exception as e:
                msg = str(e).split(":")[-1].strip()
                raise TemplateSyntaxError(msg, lineno, name, filename) from e
        elif token == TOKEN_INTEGER:
            value = int(value_str.replace("_", ""), 0)
        elif token == TOKEN_FLOAT:
            # remove all "_" first to support more Python versions
            value = literal_eval(value_str.replace("_", ""))
        elif token == TOKEN_OPERATOR:
            token = operators[value_str]

        yield Token(lineno, token, value)

def changed(self, *value: t.Any) -> bool:
    if self._last_changed_value != value:
        self._last_changed_value = value
        return True

    return False

def htmlsafe_json_dumps(
    obj: t.Any, dumps: t.Callable[..., str] | None = None, **kwargs: t.Any
) -> markupsafe.Markup:
    if dumps is None:
        dumps = json.dumps

    return markupsafe.Markup(
        dumps(obj, **kwargs)
        .replace("<", "\\u003c")
        .replace(">", "\\u003e")
        .replace("&", "\\u0026")
        .replace("'", "\\u0027")
    )

def macro_def(self, macro_ref: MacroRef, frame: Frame) -> None:
    arg_tuple = ", ".join(repr(x.name) for x in macro_ref.node.args)
    name = getattr(macro_ref.node, "name", None)
    if len(macro_ref.node.args) == 1:
        arg_tuple += ","
    self.write(
        f"Macro(environment, macro, {name!r}, ({arg_tuple}),"
        f" {macro_ref.accesses_kwargs!r}, {macro_ref.accesses_varargs!r},"
        f" {macro_ref.accesses_caller!r}, context.eval_ctx.autoescape)"
    )

def new_context(
    self,
    vars: dict[str, t.Any] | None = None,
    shared: bool = False,
    locals: t.Mapping[str, t.Any] | None = None,
) -> Context:
    return new_context(
        self.environment, self.name, self.blocks, vars, shared, self.globals, locals
    )

def modifies_known_mutable(obj: t.Any, attr: str) -> bool:
    for typespec, unsafe in _mutable_spec:
        if isinstance(obj, typespec):
            return attr in unsafe
    return False

def filter_stream(
    self, stream: "TokenStream"
) -> t.Union["TokenStream", t.Iterable["Token"]]:
    return stream

def getattr(self, obj: t.Any, attribute: str) -> t.Any:
    try:
        return getattr(obj, attribute)
    except AttributeError:
        pass
    try:
        return obj[attribute]
    except (TypeError, LookupError, AttributeError):
        return self.undefined(obj=obj, name=attribute)

def get_all(self) -> dict[str, t.Any]:
    if not self.vars:
        return self.parent
    if not self.parent:
        return self.vars
    return dict(self.parent, **self.vars)

def find_undeclared(nodes: t.Iterable[nodes.Node], names: t.Iterable[str]) -> set[str]:
    visitor = UndeclaredNameVisitor(names)
    try:
        for node in nodes:
            visitor.visit(node)
    except VisitorExit:
        pass
    return visitor.undeclared

def sync_do_rejectattr(
    context: "Context", value: "t.Iterable[V]", *args: t.Any, **kwargs: t.Any
) -> "t.Iterator[V]":
    return select_or_reject(context, value, args, kwargs, lambda x: not x, True)

def set_lineno(self, lineno: int, override: bool = False) -> "Node":
    todo = deque([self])
    while todo:
        node = todo.popleft()
        if "lineno" in node.attributes:
            if node.lineno is None or override:
                node.lineno = lineno
        todo.extend(node.iter_child_nodes())
    return self

def parse_primary(self, with_namespace: bool = False) -> nodes.Expr:
    token = self.stream.current
    node: nodes.Expr
    if token.type == "name":
        next(self.stream)
        if token.value in ("true", "false", "True", "False"):
            node = nodes.Const(token.value in ("true", "True"), lineno=token.lineno)
        elif token.value in ("none", "None"):
            node = nodes.Const(None, lineno=token.lineno)
        elif with_namespace and self.stream.current.type == "dot":
            # If namespace attributes are allowed at this point, and the next
            # token is a dot, produce a namespace reference.
            next(self.stream)
            attr = self.stream.expect("name")
            node = nodes.NSRef(token.value, attr.value, lineno=token.lineno)
        else:
            node = nodes.Name(token.value, "load", lineno=token.lineno)
    elif token.type == "string":
        next(self.stream)
        buf = [token.value]
        lineno = token.lineno
        while self.stream.current.type == "string":
            buf.append(self.stream.current.value)
            next(self.stream)
        node = nodes.Const("".join(buf), lineno=lineno)
    elif token.type in ("integer", "float"):
        next(self.stream)
        node = nodes.Const(token.value, lineno=token.lineno)
    elif token.type == "lparen":
        next(self.stream)
        node = self.parse_tuple(explicit_parentheses=True)
        self.stream.expect("rparen")
    elif token.type == "lbracket":
        node = self.parse_list()
    elif token.type == "lbrace":
        node = self.parse_dict()
    else:
        self.fail(f"unexpected {describe_token(token)!r}", token.lineno)
    return node

def get_corresponding_lineno(self, lineno: int) -> int:
    for template_line, code_line in reversed(self.debug_info):
        if code_line <= lineno:
            return template_line
    return 1

def is_internal_attribute(obj: t.Any, attr: str) -> bool:
    if isinstance(obj, types.FunctionType):
        if attr in UNSAFE_FUNCTION_ATTRIBUTES:
            return True
    elif isinstance(obj, types.MethodType):
        if attr in UNSAFE_FUNCTION_ATTRIBUTES or attr in UNSAFE_METHOD_ATTRIBUTES:
            return True
    elif isinstance(obj, type):
        if attr == "mro":
            return True
    elif isinstance(obj, (types.CodeType, types.TracebackType, types.FrameType)):
        return True
    elif isinstance(obj, types.GeneratorType):
        if attr in UNSAFE_GENERATOR_ATTRIBUTES:
            return True
    elif hasattr(types, "CoroutineType") and isinstance(obj, types.CoroutineType):
        if attr in UNSAFE_COROUTINE_ATTRIBUTES:
            return True
    elif hasattr(types, "AsyncGeneratorType") and isinstance(
        obj, types.AsyncGeneratorType
    ):
        if attr in UNSAFE_ASYNC_GENERATOR_ATTRIBUTES:
            return True
    return attr.startswith("__")

def dump(
    self,
    fp: str | t.IO[bytes],
    encoding: str | None = None,
    errors: str | None = "strict",
) -> None:
    close = False

    if isinstance(fp, str):
        if encoding is None:
            encoding = "utf-8"

        real_fp: t.IO[bytes] = open(fp, "wb")
        close = True
    else:
        real_fp = fp

    try:
        if encoding is not None:
            iterable = (x.encode(encoding, errors) for x in self)  # type: ignore
        else:
            iterable = self  # type: ignore

        if hasattr(real_fp, "writelines"):
            real_fp.writelines(iterable)
        else:
            for item in iterable:
                real_fp.write(item)
    finally:
        if close:
            real_fp.close()

def cycle(self, *args: V) -> V:
    if not args:
        raise TypeError("no items for cycling given")

    return args[self.index0 % len(args)]

def extend(self, **attributes: t.Any) -> None:
    for key, value in attributes.items():
        if not hasattr(self, key):
            setattr(self, key, value)

def test_sequence(value: t.Any) -> bool:
    try:
        len(value)
        value.__getitem__  # noqa B018
    except Exception:
        return False

    return True

def wrap_str_format(self, value: t.Any) -> t.Callable[..., str] | None:
    if not isinstance(
        value, (types.MethodType, types.BuiltinMethodType)
    ) or value.__name__ not in ("format", "format_map"):
        return None

    f_self: t.Any = value.__self__

    if not isinstance(f_self, str):
        return None

    str_type: type[str] = type(f_self)
    is_format_map = value.__name__ == "format_map"
    formatter: SandboxedFormatter

    if isinstance(f_self, Markup):
        formatter = SandboxedEscapeFormatter(self, escape=f_self.escape)
    else:
        formatter = SandboxedFormatter(self)

    vformat = formatter.vformat

    def wrapper(*args: t.Any, **kwargs: t.Any) -> str:
        if is_format_map:
            if kwargs:
                raise TypeError("format_map() takes no keyword arguments")

            if len(args) != 1:
                raise TypeError(
                    f"format_map() takes exactly one argument ({len(args)} given)"
                )

            kwargs = args[0]
            args = ()

        return str_type(vformat(f_self, args, kwargs))

    return update_wrapper(wrapper, value)

def preprocess(
    self,
    source: str,
    name: str | None = None,
    filename: str | None = None,
) -> str:
    return reduce(
        lambda s, e: e.preprocess(s, name, filename),
        self.iter_extensions(),
        str(source),
    )

def visit_Block(self, node: nodes.Block, frame: Frame) -> None:
    level = 0
    if frame.toplevel:
        # if we know that we are a child template, there is no need to
        # check if we are one
        if self.has_known_extends:
            return
        if self.extends_so_far > 0:
            self.writeline("if parent_template is None:")
            self.indent()
            level += 1

    if node.scoped:
        context = self.derive_context(frame)
    else:
        context = self.get_context_ref()

    if node.required:
        self.writeline(f"if len(context.blocks[{node.name!r}]) <= 1:", node)
        self.indent()
        self.writeline(
            f'raise TemplateRuntimeError("Required block {node.name!r} not found")',
            node,
        )
        self.outdent()

    if not self.environment.is_async and frame.buffer is None:
        self.writeline(
            f"yield from context.blocks[{node.name!r}][0]({context})", node
        )
    else:
        self.writeline(f"gen = context.blocks[{node.name!r}][0]({context})")
        self.writeline("try:")
        self.indent()
        self.writeline(
            f"{self.choose_async()}for event in gen:",
            node,
        )
        self.indent()
        self.simple_write("event", frame)
        self.outdent()
        self.outdent()
        self.writeline(
            f"finally: {self.choose_async('await gen.aclose()', 'gen.close()')}"
        )

    self.outdent(level)

def sync_do_selectattr(
    context: "Context", value: "t.Iterable[V]", *args: t.Any, **kwargs: t.Any
) -> "t.Iterator[V]":
    return select_or_reject(context, value, args, kwargs, lambda x: x, True)

def select_autoescape(
    enabled_extensions: t.Collection[str] = ("html", "htm", "xml"),
    disabled_extensions: t.Collection[str] = (),
    default_for_string: bool = True,
    default: bool = False,
) -> t.Callable[[str | None], bool]:
    enabled_patterns = tuple(f".{x.lstrip('.').lower()}" for x in enabled_extensions)
    disabled_patterns = tuple(f".{x.lstrip('.').lower()}" for x in disabled_extensions)

    def autoescape(template_name: str | None) -> bool:
        if template_name is None:
            return default_for_string
        template_name = template_name.lower()
        if template_name.endswith(enabled_patterns):
            return True
        if template_name.endswith(disabled_patterns):
            return False
        return default

    return autoescape
